/* ═══════════════════════════════════════════════════════════════════════════
   UI strings — SHARED by / (Classic, index.html) and /cinematic/.

   window.FF_I18N = { <lang>: { '<key>': '<text>' } } for the 9 languages
   (en es fr zh ar uk de sv no). English is the fallback for a missing key.
   Each page has its own small engine: Classic's t() / applyTranslations(),
   Cinematic's t() / tn() / setLang(). The language choice is shared too:
   localStorage rk_lang.

     {name}-style placeholders are filled in by the caller.
     'cin.*'      the Cinematic layout's strings (the last section of each
                  language). Counted phrases are 'cin.n.<thing>.<category>',
                  with the CLDR categories Intl.PluralRules returns for that
                  language (uk: one/few/many, ar: zero/one/two/few/many,
                  zh: other only); a missing category falls back to .other.

   Loaded synchronously in <head> by both pages as ?v=<hash> (the service
   worker serves /assets/* stale-while-revalidate): after editing this file,
   recompute `shasum -a 256 assets/i18n.js | cut -c1-8` and bump ?v= in BOTH.
   ═══════════════════════════════════════════════════════════════════════════ */
